parameters.functionScript:
const apiKey = Inputs.apiKey;
const text = Inputs.text;
if (apiKey === undefined || text === undefined) return;

const model = "gemini-3.8-flash-tts";
const resp = await fetch(
  `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`,
  {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      contents: [{ parts: [{ text }] }],
      generationConfig: {
        responseModalities: ["AUDIO"],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: "Kore" } } }
      }
    })
  }
);

if (!resp.ok) {
  throw new Error(`Gemini TTS request failed (${resp.status}): ${await resp.text()}`);
}

const data = await resp.json();
const part = data?.candidates?.[0]?.content?.parts?.[0]?.inlineData;
if (!part || !part.data) {
  throw new Error("Gemini TTS returned no audio data.");
}

Outputs.audioBase64 = part.data;
Outputs.mimeType = part.mimeType || "audio/L16;rate=24000";
